using System;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;

namespace LocalFlow {
public sealed class MetricCard : Panel {
    readonly Label number,title;
    public MetricCard(string caption){BackColor=Theme.Surface;Padding=new Padding(18);number=new Label {Dock=DockStyle.Top,Height=39,Font=new Font("Segoe UI",23,FontStyle.Bold),ForeColor=Theme.Ink};title=new Label {Text=caption,Dock=DockStyle.Top,Height=28,ForeColor=Theme.Muted};Controls.Add(title);Controls.Add(number);}
    public void Value(string text){number.Text=text;}
}
public sealed class ActivityGrid : Control {
    readonly UsageStore usage;int hover=-1,pinned=-1;
    public ActivityGrid(UsageStore value){usage=value;DoubleBuffered=true;Dock=DockStyle.Fill;BackColor=Color.White;Cursor=Cursors.Hand;MouseMove+=(s,e)=>{int next=CellAt(e.Location);if(hover!=next){hover=next;Invalidate();}};MouseLeave+=(s,e)=>{hover=-1;Invalidate();};MouseClick+=(s,e)=>{pinned=CellAt(e.Location);Invalidate();};}
    public DateTime StartDate {get{DateTime today=DateTime.Today;return today.AddDays(-(((int)today.DayOfWeek+6)%7)-175);}}
    public DateTime? HighlightedDate {get{int index=hover>=0?hover:pinned;return index<0?(DateTime?)null:StartDate.AddDays(index);}}
    int Cell {get{return Math.Max(8,Math.Min(14,(Width-40)/26-3));}}
    public Rectangle DayBounds(DateTime day){int index=(int)(day.Date-StartDate).TotalDays;return index<0||index>=182?Rectangle.Empty:new Rectangle(30+(index/7)*(Cell+3),45+(index%7)*(Cell+3),Cell,Cell);}
    int CellAt(Point point){int step=Cell+3,x=point.X-30,y=point.Y-45;if(x<0||y<0||x/step>=26||y/step>=7||x%step>=Cell||y%step>=Cell)return -1;int index=(x/step)*7+y/step;return StartDate.AddDays(index)>DateTime.Today?-1:index;}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Graphics g=e.Graphics;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;long max=Math.Max(1,usage.Data.Days.Where(d=>String.CompareOrdinal(d.Date,StartDate.ToString("yyyy-MM-dd"))>=0).Select(d=>d.Words).DefaultIfEmpty(1).Max());using(Font font=new Font("Segoe UI",9)){TextRenderer.DrawText(g,"Activity · last six months",font,new Point(0,0),Theme.Muted);int month=-1;for(int column=0;column<26;column++){DateTime date=StartDate.AddDays(column*7);if(date.Month!=month){TextRenderer.DrawText(g,date.ToString("MMM"),font,new Point(30+column*(Cell+3),24),Theme.Muted);month=date.Month;}}TextRenderer.DrawText(g,"M",font,new Point(6,44),Theme.Muted);TextRenderer.DrawText(g,"W",font,new Point(6,44+2*(Cell+3)),Theme.Muted);TextRenderer.DrawText(g,"F",font,new Point(6,44+4*(Cell+3)),Theme.Muted);
        for(int i=0;i<182;i++){DateTime date=StartDate.AddDays(i);UsageDay day=usage.Data.Days.FirstOrDefault(d=>d.Date==date.ToString("yyyy-MM-dd"));float weight=day==null?0:(float)day.Words/max;Color color=date>DateTime.Today?Color.FromArgb(252,252,252):Shade(weight);Rectangle area=DayBounds(date);using(Brush fill=new SolidBrush(color))g.FillRectangle(fill,area);if((hover>=0?hover:pinned)==i)using(Pen outline=new Pen(Theme.Accent,2))g.DrawRectangle(outline,Rectangle.Inflate(area,1,1));}
        int bottom=45+7*(Cell+3)+3;DateTime? highlighted=HighlightedDate;string detail="Hover or click a day";if(highlighted.HasValue){string key=highlighted.Value.ToString("yyyy-MM-dd");UsageDay day=usage.Data.Days.FirstOrDefault(d=>d.Date==key);detail=highlighted.Value.ToString("MMM d, yyyy")+" · "+(day==null?0:day.Words).ToString("N0")+" words";}TextRenderer.DrawText(g,detail,font,new Point(0,bottom),Theme.Ink);int legend=30+26*(Cell+3)-144;TextRenderer.DrawText(g,"Less",font,new Point(legend,bottom),Theme.Muted);for(int i=0;i<5;i++)using(Brush fill=new SolidBrush(Shade(i/4f)))g.FillRectangle(fill,legend+32+i*12,bottom+3,9,9);TextRenderer.DrawText(g,"More",font,new Point(legend+96,bottom),Theme.Muted);}}
    static Color Shade(float weight){weight=Math.Max(0,Math.Min(1,weight));return weight==0?Theme.Surface:Color.FromArgb(255-(int)(weight*31),220-(int)(weight*172),224-(int)(weight*162));}
}
public sealed class DashboardWindow : Form {
    readonly HistoryStore history;readonly UsageStore usage;readonly Action openHistory;
    readonly MetricCard words=new MetricCard("Words dictated"),speed=new MetricCard("Words / minute"),streak=new MetricCard("Day streak"),sessions=new MetricCard("Dictations");
    readonly FlowLayoutPanel recent=new FlowLayoutPanel {Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};readonly ActivityGrid grid;
    public DashboardWindow(HistoryStore entries,UsageStore statistics,Action historyAction){history=entries;usage=statistics;openHistory=historyAction;Text="Home";Font=new Font("Segoe UI",10);BackColor=Color.White;
        TableLayoutPanel layout=new TableLayoutPanel {Dock=DockStyle.Fill,Padding=new Padding(24,12,24,12),ColumnCount=1,RowCount=5};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,94));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,112));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,54));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,197));Controls.Add(layout);
        Panel welcome=new Panel {Dock=DockStyle.Fill,BackColor=Color.White};welcome.Controls.Add(new Label {Text="Your voice. Your words.",Font=new Font("Segoe UI",21,FontStyle.Bold),Location=new Point(0,4),AutoSize=true});welcome.Controls.Add(new Label {Text="Dictate anywhere. Everything stays local.",ForeColor=Theme.Muted,Location=new Point(2,45),AutoSize=true});layout.Controls.Add(welcome,0,0);
        TableLayoutPanel metrics=new TableLayoutPanel {Dock=DockStyle.Fill,ColumnCount=4,RowCount=1};foreach(MetricCard card in new[]{words,speed,streak,sessions}){metrics.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,25));card.Dock=DockStyle.Fill;card.Margin=new Padding(0,0,12,0);metrics.Controls.Add(card);}layout.Controls.Add(metrics,0,1);
        Panel heading=new Panel {Dock=DockStyle.Fill};heading.Controls.Add(new Label {Text="Recent dictations",Font=new Font("Segoe UI",12,FontStyle.Bold),Location=new Point(0,16),AutoSize=true});Button all=Theme.Button("View history");all.Anchor=AnchorStyles.Top|AnchorStyles.Right;all.Location=new Point(heading.Width-122,9);all.Click+=(s,e)=>openHistory();heading.Controls.Add(all);layout.Controls.Add(heading,0,2);layout.Controls.Add(recent,0,3);
        grid=new ActivityGrid(usage);layout.Controls.Add(grid,0,4);recent.SizeChanged+=(s,e)=>ResizeRows();history.Changed+=RefreshRecent;usage.Changed+=RefreshMetrics;RefreshMetrics();RefreshRecent();
    }
    void RefreshMetrics(){words.Value(usage.Data.Words.ToString("N0"));speed.Value(usage.Data.Seconds>0?usage.WordsPerMinute.ToString("0"):"—");streak.Value(usage.Streak(DateTime.Today).ToString());sessions.Value(usage.Data.Sessions.ToString("N0"));grid.Invalidate();}
    void RefreshRecent(){if(IsDisposed)return;recent.SuspendLayout();foreach(Control old in recent.Controls.Cast<Control>().ToArray())old.Dispose();recent.Controls.Clear();HistoryEntry[] entries=history.Snapshot().Where(e=>!e.VoiceEdit).Take(5).ToArray();if(entries.Length==0){recent.Controls.Add(new Label {Text="Your next dictation will appear here.",ForeColor=Theme.Muted,AutoSize=true,Padding=new Padding(2,22,0,0)});}foreach(HistoryEntry entry in entries){Panel row=new Panel {Width=Math.Max(200,recent.ClientSize.Width-23),Height=107,BackColor=Theme.Surface,Margin=new Padding(0,0,0,10),Padding=new Padding(16)};Label time=new Label {Text=entry.CreatedUtc.ToLocalTime().ToString("MMM d · h:mm tt")+"   "+entry.Mode,Location=new Point(15,10),Size=new Size(row.Width-30,22),ForeColor=Theme.Muted,Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right};Label text=new Label {Text=String.IsNullOrEmpty(entry.Result)?entry.Transcript:entry.Result,Location=new Point(15,34),Size=new Size(row.Width-30,31),AutoEllipsis=true,Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right};Button copy=Theme.Button("Copy"),original=Theme.Button("Original");copy.AutoSize=original.AutoSize=false;copy.MinimumSize=new Size(74,29);original.MinimumSize=new Size(94,29);copy.Size=new Size(74,29);original.Size=new Size(94,29);copy.Location=new Point(15,69);original.Location=new Point(99,69);copy.Click+=(s,e)=>Copy(String.IsNullOrEmpty(entry.Result)?entry.Transcript:entry.Result,copy);original.Click+=(s,e)=>Copy(entry.Transcript,original);row.Controls.AddRange(new Control[]{time,text,copy,original});recent.Controls.Add(row);}recent.ResumeLayout();}
    static void Copy(string text,Button button){try{if(!String.IsNullOrEmpty(text))TextClipboard.SetText(text);button.Text="Copied";}catch(System.Runtime.InteropServices.ExternalException){button.Text="Try again";}}
    void ResizeRows(){foreach(Panel row in recent.Controls.OfType<Panel>())row.Width=Math.Max(200,recent.ClientSize.Width-23);}
    protected override void Dispose(bool disposing){if(disposing){history.Changed-=RefreshRecent;usage.Changed-=RefreshMetrics;}base.Dispose(disposing);}
}
}
